      const segmentRevenue=segments.reduce((s,r)=>s+r.revenue,0),internalRevenue=m.consolidationPath?segmentRevenue*(a.eliminationStart+(a.eliminationEnd-a.eliminationStart)*t):0,revenue=segmentRevenue-internalRevenue,consolidated=m.consolidationPath?{segmentRevenue,internalRevenue,otherOperatingProfit:revenue*(a.otherProfitStart+(a.otherProfitEnd-a.otherProfitStart)*t),minority:revenue*a.minority}:{},grossPath=m.grossProfitPath?{grossProfit:segments.reduce((s,r)=>s+r.grossProfit,0),...Object.fromEntries(['research','selling','otherOperating'].map(k=>[k,revenue*(a[k+'Start']+(a[k+'End']-a[k+'Start'])*t)])),minority:revenue*a.minority}:{};
      const segmentOperatingIncome=m.grossProfitPath?grossPath.grossProfit-grossPath.research-grossPath.selling-grossPath.otherOperating:segments.reduce((s,r)=>s+r[incomeKey],0),corporateCost=m.unallocatedPath?revenue*(a.corporateStart+(a.corporateEnd-a.corporateStart)*t):0,unadjustedOperatingIncome=segmentOperatingIncome-corporateCost+(consolidated.otherOperatingProfit||0),excludedProfit=m.normalizationPath?revenue*(a.excludedProfitStart+(a.excludedProfitEnd-a.excludedProfitStart)*t):0,operatingIncome=unadjustedOperatingIncome-excludedProfit,netInterest=revenue*a.netInterest,tax=Math.max(0,operatingIncome+netInterest)*a.tax,depreciation=revenue*a.depreciation,workingCapital=(revenue-(m.consolidationPath?previousNet:previous.reduce((s,v)=>s+v,0)))*a.workingCapital,capex=revenue*(a.capexStart+(a.capexEnd-a.capexStart)*t),leasePrincipal=revenue*(a.leaseStart+(a.leaseEnd-a.leaseStart)*t),contentCash=m.contentPath?revenue*(a.contentStart+(a.contentEnd-a.contentStart)*t):0,cash=operatingIncome+netInterest-tax+depreciation-workingCapital-capex-contentCash-leasePrincipal;
      const warrantyAccrual=m.reservePath?revenue*a.warrantyAccrual:0,warrantyUse=m.reservePath?revenue*(a.warrantyUseStart+(a.warrantyUseEnd-a.warrantyUseStart)*t):0;
      years.push({year,segments,revenue,[incomeKey]:operatingIncome,netInterest,tax,depreciation,workingCapital,capex,leasePrincipal,cash:cash+warrantyAccrual-warrantyUse-revenue*(a.minority||0),...(m.contentPath?{contentCash}:{}),...grossPath,...consolidated,...(m.minorityPath?{minority:revenue*a.minority}:{}),...(m.unallocatedPath?{[m.pretaxPath?'segmentPretaxIncome':'segmentOperatingIncome']:segmentOperatingIncome,corporateCost}:{}),...(m.normalizationPath?{unadjustedOperatingIncome,excludedProfit}:{}),...(m.reservePath?{warrantyAccrual,warrantyUse}:{})});previousNet=revenue;previous=segments.map(s=>s.revenue);
