      investmentBridge={assumedValue:asset,cashPathValue:equityValue,selectedSubtotal:subtotal,selectedSubtotalPrice:subtotal!==null&&eligible?subtotal/m.security.shares.value:null,marketRemainder:eligible?remainder:null,status:!eligible?'security_unresolved':asset===null?'investment_unassessed':remainder===null||remainder<=0?'nonpositive_market_remainder':'conditional_subtotal'};
