      result.contingentLossCases=[.1,.5,1].flatMap(fraction=>[1,3,5].map(year=>{const payment=exposure*fraction,presentValue=payment/(1+a.discount)**year,stressed=equityValue==null?null:equityValue-presentValue,eligible=stressed!=null&&stressed>0;return {fraction,year,payment,presentValue,equityValue:eligible?stressed:null,price:eligible&&m.security.status==='available'?stressed/m.security.shares.value:null};}));
